<template><section><PageHeading eyebrow="THE RHYTHM OF CONVERSATION" title="在对话里，发现更多。" description="观察聊天的节奏、话题与活跃时刻。所有统计均基于已读取样本。"><div class="segment-control" aria-label="分析时间范围"><button v-for="d in [7,30,90]" :key="d" :class="{active:days===d}" :aria-pressed="days===d" @click="days=d">{{ d }} 天</button></div><button class="btn" :disabled="loading||!stats.total" @click="exportData"><UiIcon name="download" :size="14"/>导出样本</button><button class="btn btn-square" aria-label="刷新分析" :disabled="loading" @click="refresh(true)"><UiIcon name="refresh" :size="15"/></button></PageHeading><SampleNotice :sample="sample"/><div class="stats-grid content-gap"><div v-for="metric in metrics" :key="metric.label" class="stat"><div class="stat-top"><span>{{ metric.label }}</span><span class="stat-icon"><UiIcon :name="metric.icon" :size="16"/></span></div><div class="stat-value">{{ loading||error?'—':number(metric.value) }}<small>{{ metric.unit }}</small></div><div class="stat-bottom">{{ metric.note }}</div></div></div><StatePanel v-if="loading" kind="loading" title="正在读取并分析样本"/><StatePanel v-else-if="error" kind="error" title="暂时无法生成分析" :description="error" @retry="refresh(true)"/><StatePanel v-else-if="!stats.total" title="这段时间没有可分析的记录" description="切换时间范围，或检查数据服务是否有最近的消息。"/><div v-else class="analytics-grid"><article class="panel"><div class="panel-head"><div><h3>消息趋势</h3><p class="panel-subtitle">近 {{ days }} 天 · 按日聚合的样本消息</p></div><span class="pill pill-green"><i class="dot"/>{{ stats.activeDays }} 个活跃日</span></div><div class="panel-body"><div class="chart-summary"><strong>{{ number(stats.total) }}</strong><span>条消息</span></div><TrendChart :points="stats.daily"/></div></article><article class="panel"><div class="panel-head"><div><h3>一周中的聊天时刻</h3><p class="panel-subtitle">周一至周日 · 24 小时分布</p></div></div><div class="panel-body"><div class="heatmap"><template v-for="(row,day) in stats.heat" :key="day"><span class="heat-label">{{ week[day] }}</span><button v-for="(value,hour) in row" :key="hour" class="heat-cell" :style="{background:value?`color-mix(in srgb,var(--accent) ${20+value/heatMax*80}%,var(--soft))`:'var(--soft)'}" :title="`${week[day]} ${hour}:00 — ${value} 条`" :aria-label="`${week[day]} ${hour} 点，${value} 条样本消息`" @click="showHour(day,hour,value)"/></template></div><div class="heat-hours"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:00</span></div><div class="heat-scale"><span>较少</span><i v-for="opacity in [.1,.3,.5,.75,1]" :key="opacity" :style="{background:'var(--accent)',opacity}"/><span>较多</span></div><p class="scope-note">{{ hourNote||'点击任一时间格查看消息数。仅反映当前样本。' }}</p></div></article><article class="panel"><div class="panel-head"><div><h3>消息类型分布</h3><p class="panel-subtitle">每条消息归入一个主要类型</p></div><UiIcon name="chat" :size="16"/></div><div class="panel-body"><TypeDonut :items="stats.types"/></div></article><article class="panel"><div class="panel-head"><div><h3>经常提起的话题</h3><p class="panel-subtitle">本地分词统计 · 点击词语搜索</p></div><UiIcon name="text" :size="16"/></div><div class="panel-body"><div class="words"><button v-for="(word,i) in stats.words" :key="word.name" class="word" :style="{fontSize:`${Math.max(12,25-i)}px`}" :title="`出现 ${word.value} 次`" @click="searchWord(word.name)">{{ word.name }}<small style="font-size:9px;opacity:.6;margin-left:4px">{{ word.value }}</small></button></div><p class="scope-note">统计词频，不作情绪、关系或人格判断。</p></div></article><article class="panel"><div class="panel-head"><div><h3>一天中的活跃时段</h3><p class="panel-subtitle">每小时样本消息数 · 使用浏览器时区</p></div><span class="pill">{{ peakHour }}:00 最活跃</span></div><div class="panel-body"><div class="hour-bars" role="img" aria-label="24 小时消息数分布"><div v-for="(value,hour) in stats.hourly" :key="hour" class="hour-bar" :style="{height:`${value/hourMax*100}%`}" :title="`${hour}:00 — ${value} 条`"/></div><div class="hour-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:00</span></div><details class="chart-data"><summary>查看小时数据</summary><div class="native-chart-table"><table><tbody><tr v-for="(value,hour) in stats.hourly" :key="hour"><td>{{ hour }}:00</td><td>{{ value }} 条</td></tr></tbody></table></div></details></div></article><article class="panel"><div class="panel-head"><div><h3>活跃群聊</h3><p class="panel-subtitle">仅对已采样的群聊排序，非全部群排行</p></div><UiIcon name="users" :size="16"/></div><div class="panel-body"><StatePanel v-if="!stats.groups.length" title="样本里没有群聊"/><button v-for="(group,i) in stats.groups.slice(0,5)" :key="group.id" class="ranking-row" @click="openChat(group.id)"><span class="mono muted">{{ String(i+1).padStart(2,'0') }}</span><div style="flex:1;min-width:0"><div class="ranking-name"><span class="truncate">{{ group.name }}</span><strong>{{ number(group.value) }}</strong></div><div class="ranking-track"><i :style="{width:`${group.value/stats.groups[0].value*100}%`}"/></div></div><UiIcon name="chevron" :size="13"/></button></div></article></div></section></template>
<script>
import { ref,computed } from 'vue'
import { useRouter } from 'vue-router'
import useSample from '@/lib/useSample'
import { number,csvString,download,dateKey } from '@/lib/data'
import { clock } from '@/lib/demo'
import { notify } from '@/lib/workspace'
import PageHeading from '@/components/ui/PageHeading.vue'
import UiIcon from '@/components/ui/UiIcon.vue'
import StatePanel from '@/components/ui/StatePanel.vue'
import SampleNotice from '@/components/ui/SampleNotice.vue'
import TrendChart from '@/components/charts/TrendChart.vue'
import TypeDonut from '@/components/charts/TypeDonut.vue'
export default {name:'ArchiveAnalytics',components:{PageHeading,UiIcon,StatePanel,SampleNotice,TrendChart,TypeDonut},setup(){const router=useRouter(),sample=useSample(30),hourNote=ref(''),week=['一','二','三','四','五','六','日'];const metrics=computed(()=>[{label:'样本消息',value:sample.stats.value.total,unit:'条',icon:'chat',note:'当前时间范围内已读取的消息'},{label:'参与者',value:sample.stats.value.users,unit:'位',icon:'user',note:'按样本内发送者去重'},{label:'日均样本消息',value:sample.stats.value.average,unit:'条',icon:'chart',note:`样本消息 / ${sample.days.value} 个自然日`},{label:'活跃天数',value:sample.stats.value.activeDays,unit:'天',icon:'calendar',note:'至少出现一条样本消息的日期'}]);const heatMax=computed(()=>Math.max(1,...sample.stats.value.heat.flat())),hourMax=computed(()=>Math.max(1,...sample.stats.value.hourly)),peakHour=computed(()=>sample.stats.value.hourly.indexOf(Math.max(...sample.stats.value.hourly)));const exportData=()=>{download(csvString(sample.stats.value.logs,[{key:'talkerName',label:'会话'},{key:'senderName',label:'发送者'},{key:'time',label:'时间'},{key:'content',label:'内容'}]),`chatlog-样本-${sample.days.value}天-${dateKey(clock())}.csv`,'text/csv;charset=utf-8');notify(`已导出 ${sample.stats.value.total} 条样本，不是全量记录`)};return {...sample,metrics,week,heatMax,hourMax,peakHour,hourNote,number,exportData,showHour:(d,h,v)=>{hourNote.value=`星期${week[d]} ${h}:00–${h+1}:00，共 ${v} 条样本消息。`},searchWord:keyword=>router.push({path:'/chatlog',query:{keyword}}),openChat:id=>router.push({path:'/chatlog',query:{talker:id}})}}}
</script>
